function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
function persist(){try{localStorage.setItem(SAVE,saveGame(state));$('save-status').textContent='Progress saved on this device';}catch{$('save-status').textContent='Storage unavailable — export your save from Settings';}}
function hasSave(){try{return !!localStorage.getItem(SAVE);}catch{return false;}}
$('continue-game').hidden=!hasSave();
let clockLast=performance.now();
const clockDisplay=document.createElement('div');clockDisplay.id='world-clock';clockDisplay.className='world-clock';clockDisplay.title='1 hour of active play = 1 game day. Night: 20:00–06:00. Wilderness encounters are 50% more likely and 25% stronger.';
clockDisplay.innerHTML='<strong></strong><small>1 real hour = 1 game day</small><div id="timed-buffs"></div>';document.querySelector('.vitals').after(clockDisplay);
function updateClockDisplay(){if(!state)return;clockDisplay.querySelector('strong').textContent=(isNight(state)?'☾ ':'☀ ')+clockLabel(state);clockDisplay.classList.toggle('is-night',isNight(state));clockDisplay.querySelector('small').textContent=isNight(state)?'Wilderness: +50% encounters · +25% enemy strength':'1 real hour = 1 game day';$('timed-buffs').innerHTML=['strength','invisibility','meal'].filter(effect=>state.buffs?.[effect]>0).map(effect=>'<span>'+({strength:'Strength',invisibility:'Invisibility',meal:'Meal bonus'}[effect])+': '+buffTimeLeft(state,effect)+' game min left</span>').join('');}
function flushClock(refresh=true,allowHidden=false){const now=performance.now(),elapsed=now-clockLast;clockLast=now;if(!state||$('game').hidden||document.hidden&&!allowHidden||elapsed<=0||elapsed>60000)return;const before=state;state=act(state,{type:'clockTick',elapsedMs:elapsed},[],developerMode?previewRules:{});updateClockDisplay();if(refresh){if(before.gold!==state.gold||before.log.at(-1)!==state.log.at(-1)||before.mode!==state.mode)update();if(activePanel==='inventory'&&JSON.stringify(before.buffs)!==JSON.stringify(state.buffs))openPanel('inventory');persist();}}
setInterval(()=>flushClock(),1000);

function start(s){clockLast=performance.now();displayedDungeonLevel=null;finishCombat();cancelAnimationFrame(frame);state=s;$('title-screen').hidden=true;$('game').hidden=false;update();audio.unlock().then(()=>sceneMusic());frame=requestAnimationFrame(draw);if(state.mode==='town'&&state.flags.gossipGuardTown)openPanel('gossipGuard');else if(state.flags.borderTauntPending)openPanel('borderTaunt');else if(state.flags.guardTauntPending)openPanel('guardTaunt');else if(state.flags.royalQuest==='opening')openPanel('royalIntro');else if(state.mode==='ending')openPanel('ending');else if(state.casino?.active)openPanel('casino');else showLoot();}
$('new-game').onclick=()=>{if(!selectedGender){toast('Choose HIM, HER, or SHIM first.');return;}if(hasSave()){openPanel('new');return;}beginNewAdventurer();};
$('continue-game').onclick=()=>{try{start(loadGame(localStorage.getItem(SAVE)));}catch(e){toast('Cannot read save: '+e.message);}};
$('home').onclick=()=>{flushClock(false);clearTimeout(levelBannerTimer);$('level-banner').hidden=true;displayedDungeonLevel=null;finishCombat();persist();$('game').hidden=true;$('title-screen').hidden=false;refreshSlotPicker();audio.setScene('title');cancelAnimationFrame(frame);};
$('title-music').onclick=()=>{audio.setScene('title');audio.unlock();};
